import { useState } from 'react'

import { updateSpendLimit } from '../api/cards'

interface SpendLimitFieldProps {
  cardId: string
  cardLabel: string
  monthlyLimit?: number
  onSaved: (monthlyLimit: number) => void
}

export function SpendLimitField({ cardId, cardLabel, monthlyLimit = 2500, onSaved }: SpendLimitFieldProps) {
  const [draft, setDraft] = useState(monthlyLimit)
  const [optimisticLimit, setOptimisticLimit] = useState(monthlyLimit)
  const [saving, setSaving] = useState(false)

  async function handleSave() {
    setSaving(true)
    setOptimisticLimit(draft)
    try {
      await updateSpendLimit(cardId, draft)
      onSaved(draft)
    } catch {
      setOptimisticLimit(monthlyLimit)
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="flex flex-col gap-2">
      <label htmlFor="monthly-limit" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Monthly limit (USD)
      </label>
      <input
        id="monthly-limit"
        type="number"
        inputMode="numeric"
        value={draft}
        onChange={(event) => setDraft(Number(event.target.value))}
        className="w-full rounded-md border border-zinc-300 px-3 py-2 text-base tabular-nums text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
      />
      <p className="text-sm text-zinc-500 dark:text-zinc-400">
        {cardLabel} is capped at USD {optimisticLimit} this cycle.
      </p>
      <button
        type="button"
        onClick={handleSave}
        disabled={saving}
        className="self-start rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-zinc-50 hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
      >
        Save limit
      </button>
    </div>
  )
}

