import { render, screen, waitFor } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { BidHistoryFeed } from './BidHistoryFeed'
import { fetchBidPage } from './api'

vi.mock('./api', () => ({ fetchBidPage: vi.fn() }))

let observerCallback: IntersectionObserverCallback

beforeEach(() => {
  vi.mocked(fetchBidPage).mockReset()
  vi.stubGlobal('IntersectionObserver', class {
    constructor(callback: IntersectionObserverCallback) {
      observerCallback = callback
    }
    observe() {}
    disconnect() {}
  })
})

function hitSentinel(times: number) {
  for (let i = 0; i < times; i += 1) {
    observerCallback([{ isIntersecting: true } as IntersectionObserverEntry], {} as IntersectionObserver)
  }
}

describe('BidHistoryFeed', () => {
  it('hides the feed from a bidder without the lot view scope', () => {
    render(<BidHistoryFeed lotId="lot-88240" canViewBids={false} />)
    expect(screen.getByText('Bid history is limited to licensed bidders on this lot.')).toBeInTheDocument()
    expect(fetchBidPage).not.toHaveBeenCalled()
  })

  it('loads one page per sentinel hit', async () => {
    vi.mocked(fetchBidPage).mockResolvedValue({ bids: [{ id: 'bid-1', amountCents: 915000, bidderAlias: 'R. Okafor' }], nextCursor: 'c2' })
    render(<BidHistoryFeed lotId="lot-88240" canViewBids />)

    hitSentinel(3)

    await waitFor(() => expect(fetchBidPage).toHaveBeenCalledTimes(1))
  })

  it('renders the bidder alias and amount for a loaded page', async () => {
    vi.mocked(fetchBidPage).mockResolvedValue({ bids: [{ id: 'bid-1', amountCents: 915000, bidderAlias: 'R. Okafor' }], nextCursor: null })
    render(<BidHistoryFeed lotId="lot-88240" canViewBids />)
    hitSentinel(1)
    expect(await screen.findByText('R. Okafor')).toBeInTheDocument()
  })
})

import { useCallback, useEffect, useRef, useState } from 'react'

import { fetchBidPage } from './api'
import type { BidRecord } from './types'

interface BidHistoryFeedProps {
  lotId: string
  canViewBids: boolean
}

export function BidHistoryFeed({ lotId, canViewBids }: BidHistoryFeedProps) {
  const [bids, setBids] = useState<BidRecord[]>([])
  const [cursor, setCursor] = useState<string | null>(null)
  const [done, setDone] = useState(false)
  const sentinelRef = useRef<HTMLDivElement>(null)

  const loadMore = useCallback(async () => {
    const page = await fetchBidPage(lotId, cursor)
    setBids((current) => [...current, ...page.bids])
    setCursor(page.nextCursor)
    setDone(page.nextCursor === null)
  }, [lotId, cursor])

  useEffect(() => {
    const node = sentinelRef.current
    if (!node || !canViewBids || done) return
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) void loadMore()
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [canViewBids, done, loadMore])

  if (!canViewBids) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        Bid history is limited to licensed bidders on this lot.
      </p>
    )
  }

  return (
    <div className="flex flex-col gap-4">
      <ul className="flex flex-col gap-2">
        {bids.map((bid) => (
          <li key={bid.id} className="flex items-center justify-between gap-4 border-b border-zinc-100 px-4 py-3 dark:border-zinc-900">
            <span className="min-w-0 truncate text-base text-zinc-900 dark:text-zinc-100" title={bid.bidderAlias}>{bid.bidderAlias}</span>
            <span className="text-base tabular-nums text-zinc-900 dark:text-zinc-100">
              {(bid.amountCents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
            </span>
          </li>
        ))}
      </ul>
      <div ref={sentinelRef} className="h-4" aria-hidden="true" />
    </div>
  )
}

