import type { AgingWheel } from '../../types/cave'

export interface RackWindow {
  wheels: AgingWheel[]
  offsetY: number
  totalHeight: number
}

export const WHEEL_ROW_HEIGHT = 40
const OVERSCAN = 4

export function rackWindow(wheels: AgingWheel[], scrollTop: number, viewportHeight: number): RackWindow {
  const first = Math.max(0, Math.floor(scrollTop / WHEEL_ROW_HEIGHT) - OVERSCAN)
  const visibleCount = Math.floor(viewportHeight / WHEEL_ROW_HEIGHT) + OVERSCAN
  const last = Math.min(wheels.length - 1, first + visibleCount)

  return {
    wheels: wheels.slice(first, last),
    offsetY: first * WHEEL_ROW_HEIGHT,
    totalHeight: wheels.length * WHEEL_ROW_HEIGHT,
  }
}

